(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-morality-apply-advanced"]={"id":"unit22-morality-apply-advanced","unitId":"2-2","chapterIds":["2-2"],"unitType":"advanced","group":"2-2단원 · 4. 줄 서기의 도덕","name":"새 예시 적용 · 심화 5지선다","level":"심화","desc":"웹 수업의 핵심 논리 적용","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","parts":[{"name":"U22-47 · 웹 적용 · 선물의 재판매","items":[{"paragraphCount":2,"readingLabel":"18문단 · 새 예시 적용","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 18문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 18문단]\n퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다. 말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다. 물론 좌석 수는 한정되어 있다. 정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다. 하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다. 본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다. 이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.\n\n[새 적용 예시 · 원문 사례 아님]\n학급은 모두가 함께 축제를 기념하자는 뜻으로 유니폼을 무료로 나눠 주었다. 한 학생이 이를 확보한 뒤 다른 학생에게 돈을 받고 되팔았다. 유니폼은 원문의 무료 공연을 이해하기 위한 새 예시이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["비유의 사실화"],"id":"U22-47-S1","type":"mc","sent":"18문단을 바탕으로 새 예시를 바르게 설명한 것은?","options":["무료로 받은 유니폼을 되팔 때는 얼마나 벌 수 있는지만 보면 된다.","유니폼은 학급이 함께 축제를 기념하라고 준 선물이다. 혼자 되팔아 돈을 벌려면, 학급이 선물한 목적에 맞는지도 생각해야 한다.","내 것이 된 유니폼은 왜 선물했는지 생각할 필요가 없다.","유니폼 선물과 무료 공연은 나누어 주는 방법이 달라져도 의미는 달라지지 않는다.","글쓴이는 축구 유니폼을 되파는 사례를 본문에서 직접 들었다."],"answer":"유니폼은 학급이 함께 축제를 기념하라고 준 선물이다. 혼자 되팔아 돈을 벌려면, 학급이 선물한 목적에 맞는지도 생각해야 한다.","why":"학급은 함께 축제를 기념하자는 뜻으로 유니폼을 주었어요. 혼자 되팔아 돈을 버는 일이 그런 뜻에 맞는지도 따져 보아야 해요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 18문단의 내용과 비교해 보세요.","choiceReviews":{"유니폼은 학급이 함께 축제를 기념하라고 준 선물이다. 혼자 되팔아 돈을 벌려면, 학급이 선물한 목적에 맞는지도 생각해야 한다.":{"reason":"학급은 함께 축제를 기념하자는 뜻으로 유니폼을 주었어요. 혼자 되팔아 돈을 버는 일이 그런 뜻에 맞는지도 따져 보아야 해요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 18문단의 내용과 비교해 보세요.","edits":[]},"무료로 받은 유니폼을 되팔 때는 얼마나 벌 수 있는지만 보면 된다.":{"reason":"바르게 고치면: 무료로 받은 유니폼을 되팔 때는 얼마나 벌 수 있는지 외에 왜 선물했는지도 살펴야 한다.\n학급은 함께 축제를 기념하자는 뜻으로 유니폼을 주었어요. 혼자 되팔아 돈을 버는 일이 그런 뜻에 맞는지도 따져 보아야 해요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 18문단의 내용과 비교해 보세요.","edits":[{"start":26,"end":37,"before":"있는지만 보면 된다.","after":"있는지 외에 왜 선물했는지도 살펴야 한다."}]},"내 것이 된 유니폼은 왜 선물했는지 생각할 필요가 없다.":{"reason":"바르게 고치면: 내 것이 된 유니폼도 왜 선물했는지 생각할 필요가 있다.\n학급은 함께 축제를 기념하자는 뜻으로 유니폼을 주었어요. 혼자 되팔아 돈을 버는 일이 그런 뜻에 맞는지도 따져 보아야 해요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 18문단의 내용과 비교해 보세요.","edits":[{"start":7,"end":12,"before":"유니폼은 ","after":"유니폼도 "},{"start":28,"end":31,"before":"없다.","after":"있다."}]},"유니폼 선물과 무료 공연은 나누어 주는 방법이 달라져도 의미는 달라지지 않는다.":{"reason":"바르게 고치면: 유니폼 선물과 무료 공연은 나누어 주는 방법이 달라지면 의미도 달라질 수 있다.\n학급은 함께 축제를 기념하자는 뜻으로 유니폼을 주었어요. 혼자 되팔아 돈을 버는 일이 그런 뜻에 맞는지도 따져 보아야 해요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 18문단의 내용과 비교해 보세요.","edits":[{"start":26,"end":44,"before":"달라져도 의미는 달라지지 않는다.","after":"달라지면 의미도 달라질 수 있다."}]},"글쓴이는 축구 유니폼을 되파는 사례를 본문에서 직접 들었다.":{"reason":"바르게 고치면: 축구 유니폼을 되파는 사례는 웹 수업에서 본문을 이해하려고 따로 만든 예다.\n학급은 함께 축제를 기념하자는 뜻으로 유니폼을 주었어요. 혼자 되팔아 돈을 버는 일이 그런 뜻에 맞는지도 따져 보아야 해요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 18문단의 내용과 비교해 보세요.","edits":[{"start":0,"end":5,"before":"글쓴이는 ","after":""},{"start":17,"end":33,"before":"사례를 본문에서 직접 들었다.","after":"사례는 웹 수업에서 본문을 이해하려고 따로 만든 예다."}]}},"pageSpecificReasons":true,"evidence":{"title":"웹 적용 · 선물의 재판매","statement":"유니폼은 학급이 함께 축제를 기념하라고 준 선물이다. 혼자 되팔아 돈을 벌려면, 학급이 선물한 목적에 맞는지도 생각해야 한다.","explanation":"학급은 함께 축제를 기념하자는 뜻으로 유니폼을 주었어요. 혼자 되팔아 돈을 버는 일이 그런 뜻에 맞는지도 따져 보아야 해요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 18문단의 내용과 비교해 보세요.","valid":["L18:1","L18:2","L18:5","L18:6","L18:7"],"sources":[{"id":"L18","title":"줄 서기를 돈으로 살 수 있을까","label":"18문단","sentences":[{"id":"L18:1","text":"퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다.","paragraph":0,"memberIds":["L18:1"],"topic":"극장은 이 무료 공연을 모두의 축제, 시민들의 잔치로 여긴다."},{"id":"L18:2","text":"말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다.","paragraph":0,"memberIds":["L18:2"],"topic":"말하자면 도시가 시민들, 곧 자기 자신에게 주는 선물이다."},{"id":"L18:3","text":"물론 좌석 수는 한정되어 있다.","paragraph":0,"memberIds":["L18:3"],"topic":"물론 자리는 정해져 있다."},{"id":"L18:4","text":"정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다.","paragraph":0,"memberIds":["L18:4"],"topic":"그날 저녁에 모든 시민이 다 올 수는 없으니까."},{"id":"L18:5","text":"하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다.","paragraph":0,"memberIds":["L18:5"],"topic":"하지만 극장이 원래 하려던 것(취지)은 돈이 있든 없든 누구나 똑같이 공짜로 공연을 보게 하는 것이다."},{"id":"L18:6","text":"본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다.","paragraph":0,"memberIds":["L18:6"],"topic":"원래 선물이어야 할 행사에서 입장료를 받거나 암표상이 돈을 벌게 놔두면, 그 목적과 어긋난다."},{"id":"L18:7","text":"이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","paragraph":0,"memberIds":["L18:7"],"topic":"그건 모두의 축제를 개인의 돈벌이 수단(사적 이익의 도구)으로 바꿔 버리는 일이다."}]}]},"editorSourceVersion":"85c6f2861604993ea123b1baa55fecfad6565019cbfb1c499c487ebf31975d2d"}]}],"readingBlock":"morality","readingChunk":"apply","cat":"2-2단원"};})(window);
